use anyhow::{anyhow, Result};
use clap::{Parser, Subcommand};
use serde::{Deserialize, Serialize};
use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};

mod parser;
mod cli;
mod query;
mod format;

use parser::{parse_markdown, Heading, Document};
use cli::Cli;
use format::{format_list, format_tree, format_json, format_section};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Heading {
    pub level: usize,
    pub title: String,
    pub line: usize,
    pub content: String,
    pub children: Vec<Heading>,
    pub slug: String,
}

pub struct Document {
    pub headings: Vec<Heading>,
    pub raw_content: String,
    pub lines: Vec<String>,
}

fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Some(cli::Commands::AtLine { line }) => {
            let files = get_input_files(&cli.file)?;
            if files.is_empty() {
                return Err(anyhow!("No file specified"));
            }
            let content = read_file(&files[0])?;
            let doc = parser::parse_markdown(&content)?;
            // Find heading at line
            for heading in &doc.headings {
                if heading.line <= line {
                    println!("{}", heading.title);
                    return Ok(());
                }
            }
            Ok(())
        }
        None => {
            // CLI or TUI mode
            let files = get_input_files(&cli.file)?;

            if files.is_empty() {
                return Err(anyhow!("No file specified or could not read stdin"));
            }

            let content = read_file(&files[0])?;
            let doc = parser::parse_markdown(&content)?;

            if let Some(query_expr) = cli.query {
                let results = query::execute_query(&doc, &query_expr)?;
                println!("{}", results);
            } else if let Some(section) = cli.section {
                println!("{}", format_section(&doc, &section)?);
            } else if cli.tree {
                println!("{}", format_tree(&doc)?);
            } else if cli.list {
                println!("{}", format_list(&doc, cli.output.as_deref())?);
            } else if cli.count {
                println!("{}", format_count(&doc));
            } else {
                // Interactive mode - not implemented for now
                println!("Interactive mode not yet implemented");
            }

            Ok(())
        }
    }
}

fn get_input_files(files: &[PathBuf]) -> Result<Vec<PathBuf>> {
    if files.is_empty() {
        // Try to read from stdin
        let mut buffer = String::new();
        if io::stdin().read_to_string(&mut buffer).is_ok() && !buffer.is_empty() {
            // Write to temp file
            let tmp_path = PathBuf::from("/tmp/treemd_stdin.md");
            fs::write(&tmp_path, &buffer)?;
            return Ok(vec![tmp_path]);
        }
        return Ok(vec![]);
    }
    Ok(files.to_vec())
}

fn read_file(path: &Path) -> Result<String> {
    if path.to_str() == Some("-") {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;
        return Ok(buffer);
    }
    fs::read_to_string(path).map_err(|e| anyhow!("Failed to read file: {}", e))
}

fn format_count(doc: &Document) -> String {
    let mut counts = [0; 7];
    for heading in &doc.headings {
        if heading.level <= 6 {
            counts[heading.level] += 1;
        }
    }

    let mut result = String::from("Heading counts:\n");
    for level in 1..=6 {
        if counts[level] > 0 {
            let hash = "#".repeat(level);
            result.push_str(&format!("  {}: {}\n", hash, counts[level]));
        }
    }
    result.push_str(&format!("Total: {}\n", doc.headings.len()));
    result
}
EOF

