use crate::parser::{Document, Heading};
use anyhow::{anyhow, Result};
use serde_json::{json, Value};

pub fn format_list(doc: &Document, output_format: Option<&str>) -> Result<String> {
    match output_format.unwrap_or("plain") {
        "plain" => {
            let mut result = String::new();
            for heading in &doc.headings {
                let hash = "#".repeat(heading.level);
                result.push_str(&format!("{} {}\n", hash, heading.title));
            }
            Ok(result.trim_end().to_string())
        }
        "json" => format_json_full(doc),
        "tree" => format_tree(doc),
        _ => Err(anyhow!("Unknown output format")),
    }
}

pub fn format_tree(doc: &Document) -> Result<String> {
    let mut result = String::new();
    let tree = build_tree(&doc.headings);

    for (idx, heading) in tree.iter().enumerate() {
        let is_last = idx == tree.len() - 1;
        print_tree_node(heading, &mut result, "", is_last);
    }

    Ok(result.trim_end().to_string())
}

fn build_tree(headings: &[Heading]) -> Vec<Heading> {
    let mut tree = Vec::new();
    let mut stack = Vec::new();

    for heading in headings {
        while !stack.is_empty() && stack.last().unwrap().level >= heading.level {
            stack.pop();
        }

        let mut new_heading = heading.clone();
        new_heading.children = Vec::new();

        if let Some(parent) = stack.last_mut() {
            parent.children.push(new_heading);
        } else {
            tree.push(new_heading);
        }

        stack.push(new_heading);
    }

    tree
}

fn print_tree_node(heading: &Heading, result: &mut String, prefix: &str, is_last: bool) {
    let connector = if is_last { "└──" } else { "├──" };
    let hash = "#".repeat(heading.level);
    result.push_str(&format!("{}{}{} {}\n", prefix, connector, hash, heading.title));

    let extension = if is_last { "   " } else { "│  " };

    for (idx, child) in heading.children.iter().enumerate() {
        let child_is_last = idx == heading.children.len() - 1;
        print_tree_node(child, result, &format!("{}{}", prefix, extension), child_is_last);
    }
}

fn format_json_full(doc: &Document) -> Result<String> {
    let mut sections = Vec::new();

    for heading in &doc.headings {
        let section = json!({
            "id": heading.id,
            "level": heading.level,
            "title": heading.title,
            "slug": heading.slug,
            "position": {
                "line": heading.line,
                "offset": 0
            },
            "content": {
                "raw": heading.content,
                "blocks": []
            }
        });
        sections.push(section);
    }

    let output = json!({
        "document": {
            "metadata": {
                "source": null,
                "headingCount": doc.headings.len(),
                "maxDepth": doc.headings.iter().map(|h| h.level).max().unwrap_or(0),
                "wordCount": doc.raw_content.split_whitespace().count()
            },
            "sections": sections
        }
    });

    Ok(serde_json::to_string_pretty(&output).unwrap())
}

pub fn format_section(doc: &Document, section_name: &str) -> Result<String> {
    let section_lower = section_name.to_lowercase();

    // Find the heading
    let mut start_idx = None;
    for (idx, heading) in doc.headings.iter().enumerate() {
        if heading.title.to_lowercase().contains(&section_lower) {
            start_idx = Some(idx);
            break;
        }
    }

    let start_idx = start_idx.ok_or_else(|| anyhow!("Section not found"))?;
    let start_heading = &doc.headings[start_idx];

    // Find where section ends (next heading at same or higher level)
    let mut end_idx = doc.headings.len();
    for (idx, heading) in doc.headings.iter().enumerate().skip(start_idx + 1) {
        if heading.level <= start_heading.level {
            end_idx = idx;
            break;
        }
    }

    // Collect all lines in this section
    let start_line = start_heading.line - 1;
    let end_line = if end_idx < doc.headings.len() {
        doc.headings[end_idx].line - 1
    } else {
        doc.lines.len()
    };

    let mut result = String::new();
    for line in &doc.lines[start_line..end_line] {
        result.push_str(line);
        result.push('\n');
    }

    Ok(result.trim_end().to_string())
}
