            "-L" | "--level" => {
                if i + 1 >= args.len() {
                    return Err("--level requires a value".to_string());
                }
                i += 1;
                level_filter = Some(args[i].parse()
                    .map_err(|_| "Invalid level".to_string())?);
            }
            "--filter" => {
                if i + 1 >= args.len() {
                    return Err("--filter requires a value".to_string());
                }
                i += 1;
                pattern_filter = Some(args[i].clone());
            }
            "--theme" => {
                if i + 1 >= args.len() {
                    return Err("--theme requires a value".to_string());
                }
                i += 1;
                theme = Some(args[i].clone());
            }
            "--color-mode" => {
                if i + 1 >= args.len() {
                    return Err("--color-mode requires a value".to_string());
                }
                i += 1;
                color_mode = Some(args[i].clone());
            }
            "--no-images" => {
                no_images = true;
            }
            "--images" => {
                images = true;
            }
            "--setup-completions" => {
                // Ignored for now
            }
            "--query-output" => {
                // Might be used with query, but we'll handle it with query for now
                if i + 1 >= args.len() {
                    return Err("--query-output requires a value".to_string());
                }
                i += 1;
                // Skip this for now
            }
            s if s.starts_with('-') => {
                return Err(format!("Unknown option: {}", s));
            }
            _ => {
                files.push(arg.clone());
            }
        }

        i += 1;
    }

    Ok(Command::Process {
        files,
        list,
        tree,
        count,
        section,
        query,
        output_format,
        level_filter,
        pattern_filter,
        theme,
        color_mode,
        no_images,
        images,
    })
}
