#[derive(Clone, Debug)]
pub struct Heading {
    pub level: usize,
    pub title: String,
    pub line: usize,
    pub content: String,
    pub slug: String,
    pub id: String,
}

pub struct Document {
    pub headings: Vec<Heading>,
    pub raw_content: String,
    pub lines: Vec<String>,
}

pub fn parse_markdown(content: &str) -> Result<Document, String> {
    let lines: Vec<String> = content.lines().map(|l| l.to_string()).collect();
    let mut headings = Vec::new();

    for (line_num, line) in lines.iter().enumerate() {
        if let Some(heading) = parse_heading(line, line_num + 1) {
            headings.push(heading);
        }
    }

    // Extract content for each heading
    let mut flat_headings = Vec::new();
    for (i, heading) in headings.into_iter().enumerate() {
        let mut heading = heading;
        let start_line = heading.line;
        let end_line = if i + 1 < flat_headings.len() {
            flat_headings.get(i + 1).map(|h: &Heading| h.line - 1).unwrap_or(lines.len())
        } else {
            lines.len()
        };

        let content_lines: Vec<String> = lines
            .iter()
            .enumerate()
            .filter(|(idx, _)| *idx >= start_line && *idx < end_line)
            .map(|(_, line)| line.clone())
            .collect();

        heading.content = content_lines.join("\n");
        flat_headings.push(heading);
    }

    Ok(Document {
        headings: flat_headings,
        raw_content: content.to_string(),
        lines,
    })
}

fn parse_heading(line: &str, line_num: usize) -> Option<Heading> {
    let trimmed = line.trim_start();

    if !trimmed.starts_with('#') {
        return None;
    }

    // Count leading #'s
    let mut level = 0;
    for ch in trimmed.chars() {
        if ch == '#' {
            level += 1;
        } else if ch == ' ' || ch == '\t' {
            break;
        } else {
            return None;
        }
    }

    if level > 6 || level == 0 {
        return None;
    }

    // Get title
    let title_part = &trimmed[level..].trim_start();
    let title = title_part.to_string();

    let slug = slugify(&title);
    let id = format!("{}-{}", slug, line_num);

    Some(Heading {
        level,
        title,
        line: line_num,
        content: String::new(),
        slug,
        id,
    })
}

fn slugify(text: &str) -> String {
    text.to_lowercase()
        .chars()
        .map(|c| {
            if c.is_alphanumeric() || c == '-' {
                c
            } else if c.is_whitespace() {
                '-'
            } else {
                ' '
            }
        })
        .collect::<String>()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join("-")
        .chars()
        .filter(|c| *c != ' ')
        .collect()
}
