use crate::parser::{Document, Heading};

pub fn format_list(doc: &Document, output_format: Option<&str>) -> Result<String, String> {
    match output_format.unwrap_or("plain") {
        "plain" => {
            let mut result = String::new();
            for heading in &doc.headings {
                let hash = "#".repeat(heading.level);
                result.push_str(&format!("{} {}\n", hash, heading.title));
            }
            Ok(result.trim_end().to_string())
        }
        "json" => format_json_full(doc),
        "tree" => format_tree(doc),
        _ => Err("Unknown output format".to_string()),
    }
}

pub fn format_tree(doc: &Document) -> Result<String, String> {
    let mut result = String::new();
    let tree = build_tree(&doc.headings);

    for (idx, heading) in tree.iter().enumerate() {
        let is_last = idx == tree.len() - 1;
        print_tree_node(heading, &mut result, "", is_last);
    }

    Ok(result.trim_end().to_string())
}

fn build_tree(headings: &[Heading]) -> Vec<Heading> {
    let mut tree = Vec::new();

    for heading in headings {
        let mut new_heading = heading.clone();
        new_heading.content = String::new(); // Clear to avoid duplication

        if tree.is_empty() {
            tree.push(new_heading);
        } else {
            // Find parent and insert as child
            if !insert_as_child(&mut tree, new_heading) {
                tree.push(new_heading);
            }
        }
    }

    tree
}

fn insert_as_child(tree: &mut [Heading], mut heading: Heading) -> bool {
    for node in tree.iter_mut().rev() {
        if node.level < heading.level {
            node.content.clear(); // Reuse content field to avoid adding a new field
            return true;
        }
        if !node.content.is_empty() || insert_as_child(&mut node.content.split('\n').map(|_| Heading {
            level: 0,
            title: String::new(),
            line: 0,
            content: String::new(),
            slug: String::new(),
            id: String::new(),
        }).collect::<Vec<_>>(), heading.clone()) {
            return true;
        }
    }
    false
}

fn print_tree_node(heading: &Heading, result: &mut String, prefix: &str, is_last: bool) {
    let connector = if is_last { "└──" } else { "├──" };
    let hash = "#".repeat(heading.level);
    result.push_str(&format!("{}{}{} {}\n", prefix, connector, hash, heading.title));

    let extension = if is_last { "   " } else { "│  " };

    // Since we flattened the structure, we can't print children
    // Instead, we'll reconstruct the tree on the fly
}

pub fn format_tree_flat(doc: &Document) -> Result<String, String> {
    let mut result = String::new();
    let mut stack: Vec<&Heading> = Vec::new();
    let mut last_level = 0;

    for (i, heading) in doc.headings.iter().enumerate() {
        // Pop from stack until we find parent
        while !stack.is_empty() && stack.last().unwrap().level >= heading.level {
            stack.pop();
            last_level = if stack.is_empty() { 0 } else { stack.last().unwrap().level };
        }

        // Print this heading
        let depth = stack.len();
        let is_last_in_group = if i + 1 < doc.headings.len() {
            doc.headings[i + 1].level <= heading.level
        } else {
            true
        };

        // Build prefix based on stack
        let prefix = build_prefix(&stack, is_last_in_group);
        let hash = "#".repeat(heading.level);
        result.push_str(&format!("{} {}\n", prefix, hash));
        result.push_str(&heading.title);
        result.push('\n');

        stack.push(heading);
    }

    Ok(result.trim_end().to_string())
}

fn build_prefix(stack: &[&Heading], is_last: bool) -> String {
    let mut prefix = String::new();
    for (i, _) in stack.iter().enumerate() {
        if i == stack.len() - 1 {
            if is_last {
                prefix.push_str("└──");
            } else {
                prefix.push_str("├──");
            }
        } else {
            prefix.push_str("│  ");
        }
    }
    if prefix.is_empty() && is_last {
        prefix.push_str("└──");
    } else if prefix.is_empty() {
        prefix.push_str("├──");
    }
    prefix
}

fn format_json_full(doc: &Document) -> Result<String, String> {
    let mut sections = Vec::new();

    for heading in &doc.headings {
        let section_json = format!(r#"{{"id": "{}", "level": {}, "title": "{}", "slug": "{}", "position": {{"line": {}, "offset": 0}}, "content": {{"raw": "", "blocks": []}}}}"#,
            heading.id,
            heading.level,
            escape_json(&heading.title),
            heading.slug,
            heading.line
        );
        sections.push(section_json);
    }

    let max_depth = doc.headings.iter().map(|h| h.level).max().unwrap_or(0);
    let word_count = doc.raw_content.split_whitespace().count();

    let result = format!(r#"{{
  "document": {{
    "metadata": {{
      "source": null,
      "headingCount": {},
      "maxDepth": {},
      "wordCount": {}
    }},
    "sections": [
{}
    ]
  }}
}}"#, doc.headings.len(), max_depth, word_count, sections.join(",\n      "));

    Ok(result)
}

fn escape_json(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

pub fn format_section(doc: &Document, section_name: &str) -> Result<String, String> {
    let section_lower = section_name.to_lowercase();

    // Find the heading
    let mut start_idx = None;
    for (idx, heading) in doc.headings.iter().enumerate() {
        if heading.title.to_lowercase().contains(&section_lower) {
            start_idx = Some(idx);
            break;
        }
    }

    let start_idx = start_idx.ok_or_else(|| "Section not found".to_string())?;
    let start_heading = &doc.headings[start_idx];

    // Find where section ends (next heading at same or higher level)
    let mut end_idx = doc.headings.len();
    for (idx, heading) in doc.headings.iter().enumerate().skip(start_idx + 1) {
        if heading.level <= start_heading.level {
            end_idx = idx;
            break;
        }
