use crate::parser::Document;

pub fn execute_query(doc: &Document, query: &str) -> Result<String, String> {
    let query = query.trim();

    match query {
        ".h" | ".heading" => {
            let mut result = String::new();
            for heading in &doc.headings {
                let hash = "#".repeat(heading.level);
                result.push_str(&format!("{} {}\n", hash, heading.title));
            }
            Ok(result.trim_end().to_string())
        }
        ".h | text" | ".heading | text" => {
            let mut result = String::new();
            for heading in &doc.headings {
                result.push_str(&format!("{}\n", heading.title));
            }
            Ok(result.trim_end().to_string())
        }
        _ if query.starts_with(".h") && query.contains('|') => {
            // Split by pipe
            let parts: Vec<&str> = query.split('|').map(|s| s.trim()).collect();
            if parts.len() == 2 && parts[1] == "text" {
                let mut result = String::new();
                for heading in &doc.headings {
                    result.push_str(&format!("{}\n", heading.title));
                }
                return Ok(result.trim_end().to_string());
            }
            Err("Unsupported query".to_string())
        }
        _ => Err("Unsupported query".to_string()),
    }
}
