use crate::parser::{Document, Heading};

pub fn format_list(doc: &Document, output_format: Option<&str>) -> Result<String, String> {
    match output_format.unwrap_or("plain") {
        "plain" => {
            let mut result = String::new();
            for heading in &doc.headings {
                let hash = "#".repeat(heading.level);
                result.push_str(&format!("{} {}\n", hash, heading.title));
            }
            Ok(result.trim_end().to_string())
        }
        "json" => format_json_full(doc),
        "tree" => format_tree(doc),
        _ => Err("Unknown output format".to_string()),
    }
}

pub fn format_tree(doc: &Document) -> Result<String, String> {
    let mut result = String::new();
    let mut stack: Vec<usize> = Vec::new(); // Track heading indices

    for (i, heading) in doc.headings.iter().enumerate() {
        // Pop from stack until we find parent or empty
        while !stack.is_empty() {
            let parent_idx = *stack.last().unwrap();
            if doc.headings[parent_idx].level < heading.level {
                break;
            }
            stack.pop();
        }

        // Check if this is the last heading at this level
        let is_last = if i + 1 < doc.headings.len() {
            doc.headings[i + 1].level <= heading.level
        } else {
            true
        };

        // Build prefix
        let mut prefix = String::new();
        for j in 0..stack.len() {
            let next_idx = if j + 1 < stack.len() {
                stack[j + 1]
            } else {
                i
            };

            let next_level = doc.headings[next_idx].level;
            let curr_level = doc.headings[stack[j]].level;

            if j < stack.len() - 1 {
                // Check if parent needs continuation
                let check_idx = stack[j];
                let is_parent_last = if check_idx + 1 < doc.headings.len() {
                    doc.headings[check_idx + 1].level <= curr_level
                } else {
                    true
                };
                prefix.push_str(if is_parent_last { "   " } else { "│  " });
            }
        }

        if !stack.is_empty() {
            prefix.push_str(if is_last { "└──" } else { "├──" });
        } else {
            prefix.push_str("└──");
        }

        let hash = "#".repeat(heading.level);
        result.push_str(&format!("{}{} {}\n", prefix, hash, heading.title));

        stack.push(i);
    }

    Ok(result.trim_end().to_string())
}

fn format_json_full(doc: &Document) -> Result<String, String> {
    let mut sections = Vec::new();

    for heading in &doc.headings {
        let section_json = format!(r#"{{"id": "{}", "level": {}, "title": "{}", "slug": "{}", "position": {{"line": {}, "offset": 0}}, "content": {{"raw": "", "blocks": []}}}}"#,
            heading.id,
            heading.level,
            escape_json(&heading.title),
            heading.slug,
            heading.line
        );
        sections.push(section_json);
    }

    let max_depth = doc.headings.iter().map(|h| h.level).max().unwrap_or(0);
    let word_count = doc.raw_content.split_whitespace().count();

    let result = format!(r#"{{
  "document": {{
    "metadata": {{
      "source": null,
      "headingCount": {},
      "maxDepth": {},
      "wordCount": {}
    }},
    "sections": [
{}
    ]
  }}
}}"#, doc.headings.len(), max_depth, word_count, sections.iter().map(|s| format!("      {}", s)).collect::<Vec<_>>().join(",\n"));

    Ok(result)
}

fn escape_json(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}

pub fn format_section(doc: &Document, section_name: &str) -> Result<String, String> {
    let section_lower = section_name.to_lowercase();

    // Find the heading
    let mut start_idx = None;
    for (idx, heading) in doc.headings.iter().enumerate() {
        if heading.title.to_lowercase().contains(&section_lower) {
            start_idx = Some(idx);
            break;
        }
    }

    let start_idx = start_idx.ok_or_else(|| "Section not found".to_string())?;
    let start_heading = &doc.headings[start_idx];

    // Find where section ends (next heading at same or higher level)
    let mut end_idx = doc.headings.len();
    for (idx, heading) in doc.headings.iter().enumerate().skip(start_idx + 1) {
        if heading.level <= start_heading.level {
            end_idx = idx;
            break;
        }
    }

    // Collect all lines in this section
    let start_line = start_heading.line - 1;
    let end_line = if end_idx < doc.headings.len() {
        doc.headings[end_idx].line - 1
    } else {
        doc.lines.len()
    };

    let mut result = String::new();
    for line in &doc.lines[start_line..end_line] {
        result.push_str(line);
        result.push('\n');
    }

    Ok(result.trim_end().to_string())
}

pub fn format_count(doc: &Document) -> String {
    let mut counts = [0; 7];
    for heading in &doc.headings {
        if heading.level <= 6 {
            counts[heading.level] += 1;
        }
    }

    let mut result = String::from("Heading counts:\n");
    for level in 1..=6 {
        if counts[level] > 0 {
            let hash = "#".repeat(level);
            result.push_str(&format!("  {}: {}\n", hash, counts[level]));
        }
    }
    result.push_str(&format!("Total: {}\n", doc.headings.len()));
    result
}
