pub fn format_tree(doc: &Document) -> Result<String, String> {
    let mut result = String::new();

    let mut printed = vec![false; doc.headings.len()];

    for (i, heading) in doc.headings.iter().enumerate() {
        if printed[i] {
            continue;
        }

        // Only start with root nodes (level 1)
        if heading.level == 1 || (i > 0 && doc.headings[i - 1].level >= heading.level) {
            print_tree_recursive(&doc.headings, i, &mut printed, &mut result, "", true);
        }
    }

    Ok(result.trim_end().to_string())
}

fn print_tree_recursive(
    headings: &[Heading],
    idx: usize,
    printed: &mut [bool],
    result: &mut String,
    prefix: &str,
    is_last: bool,
) {
    if idx >= headings.len() || printed[idx] {
        return;
    }

    printed[idx] = true;

    let connector = if is_last { "└──" } else { "├──" };
    let hash = "#".repeat(headings[idx].level);
    result.push_str(&format!("{}{}{} {}\n", prefix, connector, hash, headings[idx].title));

    let extension = if is_last { "   " } else { "│  " };

    // Find all direct children
    let current_level = headings[idx].level;
    let mut child_idx = idx + 1;
    let mut child_count = 0;

