pub enum Command {
    Help,
    Version,
    QueryHelp,
    AtLine {
        line: usize,
        files: Vec<String>,
    },
    Process {
        files: Vec<String>,
        list: bool,
        tree: bool,
        count: bool,
        section: Option<String>,
        query: Option<String>,
        output_format: Option<String>,
        level_filter: Option<usize>,
        pattern_filter: Option<String>,
        theme: Option<String>,
        color_mode: Option<String>,
        no_images: bool,
        images: bool,
    },
}

pub fn parse_args(args: &[String]) -> Result<Command, String> {
    if args.len() < 2 {
        return Ok(Command::Process {
            files: vec![],
            list: false,
            tree: false,
            count: false,
            section: None,
            query: None,
            output_format: None,
            level_filter: None,
            pattern_filter: None,
            theme: None,
            color_mode: None,
            no_images: false,
            images: false,
        });
    }

    let mut files = Vec::new();
    let mut list = false;
    let mut tree = false;
    let mut count = false;
    let mut section = None;
    let mut query = None;
    let mut output_format = None;
    let mut level_filter = None;
    let mut pattern_filter = None;
    let mut theme = None;
    let mut color_mode = None;
    let mut no_images = false;
    let mut images = false;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => {
                return Ok(Command::Help);
            }
            "-V" | "--version" => {
                return Ok(Command::Version);
            }
            "--query-help" => {
                return Ok(Command::QueryHelp);
            }
            "help" => {
                return Ok(Command::Help);
            }
            "at-line" => {
                if i + 1 >= args.len() {
                    return Err("at-line requires a line number".to_string());
                }
                i += 1;
                let line: usize = args[i].parse()
                    .map_err(|_| "Invalid line number".to_string())?;

                // Collect remaining args as files
                let mut at_line_files = Vec::new();
                for j in (i + 1)..args.len() {
                    at_line_files.push(args[j].clone());
                }

                return Ok(Command::AtLine {
                    line,
                    files: at_line_files,
                });
            }
            "-l" | "--list" => {
                list = true;
            }
            "--tree" => {
                tree = true;
            }
            "--count" => {
                count = true;
            }
            "-s" | "--section" => {
                if i + 1 >= args.len() {
                    return Err("--section requires a value".to_string());
                }
                i += 1;
                section = Some(args[i].clone());
            }
            "-q" | "--query" => {
                if i + 1 >= args.len() {
                    return Err("--query requires a value".to_string());
                }
                i += 1;
                query = Some(args[i].clone());
            }
            "-o" | "--output" => {
                if i + 1 >= args.len() {
                    return Err("--output requires a value".to_string());
                }
                i += 1;
                output_format = Some(args[i].clone());
            }
            "-L" | "--level" => {
                if i + 1 >= args.len() {
                    return Err("--level requires a value".to_string());
                }
                i += 1;
                level_filter = Some(args[i].parse()
                    .map_err(|_| "Invalid level".to_string())?);
            }
